import{_ as i,a0 as p,w as a,s as f,ao as l,I as r,x as s,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux有问必答：如何扩展XFS文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何扩展XFS文件系统 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何扩展XFS文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何扩展XFS文件系统 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system","title":"Linux有问必答：如何扩展XFS文件系统","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system.md","filePath":"[post].md"}'),x={name:"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system.md"};function d(m,t,u,_,S,F){const e=p("Link");return a(),f("div",null,[t[11]||(t[11]=l(`<h1 id="linux有问必答-如何扩展xfs文件系统" tabindex="-1">Linux有问必答：如何扩展XFS文件系统 <a class="header-anchor" href="#linux有问必答-如何扩展xfs文件系统" aria-label="Permalink to “Linux有问必答：如何扩展XFS文件系统”">​</a></h1><blockquote><p><strong>问题</strong>：我的磁盘上有额外的空间，所以我想要扩展其上创建的现存的XFS文件系统，以完全使用额外空间。怎样才是扩展XFS文件系统的正确途径？</p></blockquote><p>XFS是一个开源的（GPL）日志文件系统，最初由硅谷图形（SGI）开发，现在大多数的Linux发行版都支持。事实上，XFS已被最新的CentOS/RHEL 7采用，成为其默认的文件系统。在其众多的特性中，包含了“在线调整大小”这一特性，使得现存的XFS文件系统在已经挂载的情况下可以进行扩展。然而，对于XFS文件系统的<strong>缩减</strong>却还没有支持。</p><p>要扩展一个现存的XFS文件系统，你可以使用命令行工具xfs_growfs，这在大多数Linux发行版上都默认可用。由于XFS支持在线调整大小，目标文件系统可以挂在，也可以不挂载。</p><p>下面展示了<strong>xfs_growfs</strong>的基本用法：</p><p><img src="https://farm6.staticflickr.com/5551/14915082088_b4e29af3cf_z.jpg" alt=""></p><p>作为目标XFS文件系统来扩展，你可以指定挂载点、磁盘分区或者逻辑卷（在使用LVM时），使用数据块数量来指定新的XFS文件系统的大小。你可以使用xfs_info命令行工具来检查数据块大小和数量：</p><p><img src="https://farm6.staticflickr.com/5584/14915075270_cd272d4468_z.jpg" alt=""></p><p>要将XFS文件扩展到1986208：</p><pre><code>$ sudo xfs_growfs /dev/centos/root -D 1986208
</code></pre><p>如果你不使用“-D”选项来指定大小，xfs_growfs将会自动扩展XFS文件系统到最大的可用大小。</p><pre><code>$ sudo xfs_growfs /dev/centos/root
</code></pre><p><img src="https://farm6.staticflickr.com/5569/14914950529_ddfb71c8dd_z.jpg" alt=""></p><p>注意，当你扩展一个现存的XFS文件系统时，必须准备好事先添加用于XFS文件系统扩展的空间。这虽然是很显然的事，但是如果在所在的分区或磁盘卷上没有空闲空间可用的话，xfs_growfs就没有办法了。同时，如果你尝试扩展XFS文件系统大小到超过磁盘分区或卷的大小，xfs_growfs将会失败。</p><p><img src="https://farm4.staticflickr.com/3870/15101281542_98a49a7c3a_z.jpg" alt=""></p><hr>`,16)),r("p",null,[t[1]||(t[1]=s("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/expand-xfs-file-system.html"},{default:n(()=>[...t[0]||(t[0]=[s("http://ask.xmodulo.com/expand-xfs-file-system.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=s("译者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[2]||(t[2]=[s("GOLinux",-1)])]),_:1}),t[5]||(t[5]=s(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=s("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[s("LCTT",-1)])]),_:1}),t[9]||(t[9]=s(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[s("Linux中国",-1)])]),_:1}),t[10]||(t[10]=s(" 荣誉推出",-1))])])}const w=i(x,[["render",d]]);export{L as __pageData,w as default};
